function renderPopups(ctx) {
  for (let i = 0; i < G.popups.length; i++) {
    const p = G.popups[i];
    ctx.globalAlpha = p.alpha;
    ctx.fillStyle = p.color;
    ctx.font = 'bold 16px "Segoe UI","PingFang SC",sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = 'rgba(0,0,0,0.5)';
    ctx.shadowBlur = 3;
    ctx.fillText(p.text, p.x, p.y);
    ctx.shadowBlur = 0;
  }
  ctx.globalAlpha = 1;
}

/* =========================== 连击系统 =========================== */
function addCombo(type) {
  G.combo++;
  if (G.combo > G.maxCombo) G.maxCombo = G.combo;
  const bonus = G.combo * 10 * G.player.scoreMultiplier;
  G.coinScore += bonus;
  const px = G.player.x;
  const py = G.player.y - 60;
  if (G.combo >= 5) {
    spawnPopup(px, py, G.combo + 'x COMBO! +' + bonus, '#ffdd00');
  } else if (G.combo >= 3) {
    spawnPopup(px, py, '+' + bonus, '#ffaa00');
  }
}

function resetCombo() {
  if (G.combo >= 5) {
    spawnPopup(G.player.x, G.player.y - 40, 'COMBO LOST', '#ff4444');
  }
  G.combo = 0;
}

/* =========================== 渲染 =========================== */
function render() {
  const ctx = G.ctx;
  ctx.clearRect(0, 0, G.W, G.H);
  ctx.save();
  if (G.shakeDuration > 0) {
    ctx.translate(
      (Math.random() - 0.5) * G.shakeX * 2,
      (Math.random() - 0.5) * G.shakeY * 2
    );
  }
  renderBackground(ctx);
  renderEntities(ctx);
  renderParticles(ctx);
  renderPopups(ctx);
  ctx.restore();
  renderEffects(ctx);
  renderUI(ctx);
}

function renderBackground(ctx) {
  ctx.drawImage(G.offscreen.sky, 0, 0);
  const cityOffset = (G.distance * PARALLAX_FAR) % (G.W * 3);
  ctx.drawImage(G.offscreen.city, -cityOffset, G.vanishY - 30, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);
  const nearOffset = (G.distance * PARALLAX_NEAR) % (G.W * 2);
  ctx.drawImage(G.offscreen.nearCity, -nearOffset, G.vanishY + 10, G.W, G.H*0.35, 0, G.vanishY + 10, G.W, G.H*0.35);
  drawGround(ctx);
  drawTracks(ctx);
}

function renderEntities(ctx) {
  const entities = [];
  for (let i = 0; i < G.obstacles.length; i++) {
    const o = G.obstacles[i];
    if (!o.active) continue;
    entities.push({ type:'obstacle', obj:o, dist:o.dist, lane:o.lane });
  }
  for (let i = 0; i < G.coins.length; i++) {
    const c = G.coins[i];
    if (!c.active || c.collected) continue;
    entities.push({ type:'coin', obj:c, dist:c.dist, lane:c.lane });
  }
  for (let i = 0; i < G.powerups.length; i++) {
    const pu = G.powerups[i];
    if (!pu.active || pu.collected) continue;
    entities.push({ type:'powerup', obj:pu, dist:pu.dist, lane:pu.lane });
  }
  entities.sort((a, b) => b.dist - a.dist);
  const frontEntities = entities.filter(e => e.dist > 0);
  const behindEntities = entities.filter(e => e.dist <= 0);

  frontEntities.forEach(e => {
    const s = worldToScreen(e.dist);
    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
    const sx = laneX(e.lane, e.dist);
    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
  });
  drawPlayer(ctx);
  behindEntities.forEach(e => {
    const s = worldToScreen(e.dist);
    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
    const sx = laneX(e.lane, e.dist);
    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
  });
}

function renderParticles(ctx) {
  for (let i = 0; i < G.particles.length; i++) {
    const p = G.particles[i];
    if (!p.active) continue;
    const alpha = p.life / p.maxLife;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
  }
  ctx.globalAlpha = 1;
}

function renderEffects(ctx) {

